import { getElement } from '../../utils/functional';

class SummaryLineItems {
  constructor() {
    this.init = this.init.bind(this);
    this.updateSummaryLineItemHtml = this.updateSummaryLineItemHtml.bind(this);
    this.detectXhrRequests = this.detectXhrRequests.bind(this);
    this.init();
  }

  init() {
    if (this.lineItemsHtml && this.summaryLineItemsEl) {
      this.updateSummaryLineItemHtml();
      this.detectXhrRequests();
    }
  }

  updateSummaryLineItemHtml() {
    this.summaryLineItemsEl.innerHTML = this.lineItemsHtml;
  }

  detectXhrRequests() {
    const context = this;
    const open = window.XMLHttpRequest.prototype.open;

    function openReplacement() {
      this.addEventListener('load', function () {
        if (this.readyState === 4) {
          context.updateSummaryLineItemHtml();
        }
      });
      return open.apply(this, arguments);
    }

    window.XMLHttpRequest.prototype.open = openReplacement;
  }

  get summaryLineItemsEl() {
    return getElement('[data-order-summary-section="line-items"]');
  }

  get lineItemsEl() {
    return getElement('.js-Checkout_LineItems');
  }

  get lineItemsHtml() {
    if (!this.lineItemsEl || !this.lineItemsEl.innerHTML.length) return null;
    return this.lineItemsEl.innerHTML;
  }

}

function summaryLineItems() {
  return new SummaryLineItems();
}

summaryLineItems();